#[derive(Debug, Clone, PartialEq)]
pub struct PrimitiveShape {
    pub network_id: u64,
    pub r#type: Option<PrimitiveShapeType>,
    pub location: Option<Vec3f>,
    pub scale: Option<f32>,
    pub rotation: Option<Vec3f>,
    pub total_time_left: Option<f32>,
    pub max_render_distance: Option<f32>,
    pub color: Option<i32>,
    pub dimension_id: Option<i32>,
    pub attached_to_entity_id: Option<i64>,
    pub extra_shape_data: PrimitiveShapeExtraShapeData,
}
impl PrimitiveShape {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let f_network_id = (|| -> Result<_> { Ok(read_varint64(r)?) })()
            .map_err(|e| e.at("PrimitiveShape.network_id"))?;
        let f_type = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(PrimitiveShapeType::read(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.type"))?;
        let f_location = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(Vec3f::read(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.location"))?;
        let f_scale = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(read_lf32(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.scale"))?;
        let f_rotation = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(Vec3f::read(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.rotation"))?;
        let f_total_time_left = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(read_lf32(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.total_time_left"))?;
        let f_max_render_distance = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(read_lf32(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.max_render_distance"))?;
        let f_color = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(read_li32(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.color"))?;
        let f_dimension_id = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(read_zigzag32(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.dimension_id"))?;
        let f_attached_to_entity_id = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(read_zigzag64(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.attached_to_entity_id"))?;
        let f_extra_shape_data = (|| -> Result<_> {
            Ok(if f_type == Some(PrimitiveShapeType::Line) {
                PrimitiveShapeExtraShapeData::Line(ShapeLine::read(r)?)
            } else if f_type == Some(PrimitiveShapeType::Box) {
                PrimitiveShapeExtraShapeData::Box(ShapeBox::read(r)?)
            } else if f_type == Some(PrimitiveShapeType::Sphere) {
                PrimitiveShapeExtraShapeData::Sphere(ShapeSphere::read(r)?)
            } else if f_type == Some(PrimitiveShapeType::Circle) {
                PrimitiveShapeExtraShapeData::Circle(ShapeCircle::read(r)?)
            } else if f_type == Some(PrimitiveShapeType::Text) {
                PrimitiveShapeExtraShapeData::Text(ShapeText::read(r)?)
            } else if f_type == Some(PrimitiveShapeType::Arrow) {
                PrimitiveShapeExtraShapeData::Arrow(ShapeArrow::read(r)?)
            } else {
                PrimitiveShapeExtraShapeData::Default
            })
        })()
        .map_err(|e| e.at("PrimitiveShape.extra_shape_data"))?;
        Ok(Self {
            network_id: f_network_id,
            r#type: f_type,
            location: f_location,
            scale: f_scale,
            rotation: f_rotation,
            total_time_left: f_total_time_left,
            max_render_distance: f_max_render_distance,
            color: f_color,
            dimension_id: f_dimension_id,
            attached_to_entity_id: f_attached_to_entity_id,
            extra_shape_data: f_extra_shape_data,
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        write_varint64(w, self.network_id);
        match &self.r#type {
            Some(x0) => {
                write_bool(w, true);
                x0.write(w);
            }
            None => write_bool(w, false),
        }
        match &self.location {
            Some(x0) => {
                write_bool(w, true);
                x0.write(w);
            }
            None => write_bool(w, false),
        }
        match &self.scale {
            Some(x0) => {
                write_bool(w, true);
                write_lf32(w, *x0);
            }
            None => write_bool(w, false),
        }
        match &self.rotation {
            Some(x0) => {
                write_bool(w, true);
                x0.write(w);
            }
            None => write_bool(w, false),
        }
        match &self.total_time_left {
            Some(x0) => {
                write_bool(w, true);
                write_lf32(w, *x0);
            }
            None => write_bool(w, false),
        }
        match &self.max_render_distance {
            Some(x0) => {
                write_bool(w, true);
                write_lf32(w, *x0);
            }
            None => write_bool(w, false),
        }
        match &self.color {
            Some(x0) => {
                write_bool(w, true);
                write_li32(w, *x0);
            }
            None => write_bool(w, false),
        }
        match &self.dimension_id {
            Some(x0) => {
                write_bool(w, true);
                write_zigzag32(w, *x0);
            }
            None => write_bool(w, false),
        }
        match &self.attached_to_entity_id {
            Some(x0) => {
                write_bool(w, true);
                write_zigzag64(w, *x0);
            }
            None => write_bool(w, false),
        }
        match &self.extra_shape_data {
            PrimitiveShapeExtraShapeData::Line(x0) => {
                x0.write(w);
            }
            PrimitiveShapeExtraShapeData::Box(x0) => {
                x0.write(w);
            }
            PrimitiveShapeExtraShapeData::Sphere(x0) => {
                x0.write(w);
            }
            PrimitiveShapeExtraShapeData::Circle(x0) => {
                x0.write(w);
            }
            PrimitiveShapeExtraShapeData::Text(x0) => {
                x0.write(w);
            }
            PrimitiveShapeExtraShapeData::Arrow(x0) => {
                x0.write(w);
            }
            PrimitiveShapeExtraShapeData::Default => {}
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum PrimitiveShapeType {
    Line,
    Box,
    Sphere,
    Circle,
    Text,
    Arrow,
    Unknown(i64),
}
impl PrimitiveShapeType {
    pub fn from_raw(v: i64) -> Self {
        match v {
            0 => Self::Line,
            1 => Self::Box,
            2 => Self::Sphere,
            3 => Self::Circle,
            4 => Self::Text,
            5 => Self::Arrow,
            v => Self::Unknown(v),
        }
    }
    pub fn to_raw(self) -> i64 {
        match self {
            Self::Line => 0,
            Self::Box => 1,
            Self::Sphere => 2,
            Self::Circle => 3,
            Self::Text => 4,
            Self::Arrow => 5,
            Self::Unknown(v) => v,
        }
    }
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        Ok(Self::from_raw(read_u8(r)? as i64))
    }
    pub fn write(&self, w: &mut BytesMut) {
        write_u8(w, self.to_raw() as u8)
    }
}

