#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct CommandFlags {
    pub unused: u8,
    pub collapse_enum: u8,
    pub has_semantic_constraint: u8,
    pub as_chained_command: u8,
    pub unknown2: u8,
}
impl CommandFlags {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let bits = take(r, 1)?
            .iter()
            .fold(0u64, |acc, b| (acc << 8) | *b as u64);
        Ok(Self {
            unused: {
                let v = (bits >> 7) & 1;
                v as u8
            },
            collapse_enum: {
                let v = (bits >> 6) & 1;
                v as u8
            },
            has_semantic_constraint: {
                let v = (bits >> 5) & 1;
                v as u8
            },
            as_chained_command: {
                let v = (bits >> 4) & 1;
                v as u8
            },
            unknown2: {
                let v = (bits >> 0) & 15;
                v as u8
            },
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        let mut bits = 0u64;
        bits |= ((self.unused as u64) & 1) << 7;
        bits |= ((self.collapse_enum as u64) & 1) << 6;
        bits |= ((self.has_semantic_constraint as u64) & 1) << 5;
        bits |= ((self.as_chained_command as u64) & 1) << 4;
        bits |= ((self.unknown2 as u64) & 15) << 0;
        write_slice(w, &bits.to_be_bytes()[7..]);
    }
}

